//! Meter metadata follows the six ordered HTML gauge points.
use super::*;
fn fixture()->(Document,Forms,Page){
 let mut d=crate::html::parse("<html><body><label id=label for=meter>Capacity</label><meter id=meter min=10 max=30 value=20 low=15 high=25 optimum=18>Fallback</meter><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;
 let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://meter-numeric.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)
}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn meter_numeric_canonical_descriptors_and_ordered_initial_points(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('meter'),P=HTMLMeterElement.prototype;for(var key of ['value','min','max','low','high','optimum']){var a=Object.getOwnPropertyDescriptor(P,key);if(!a||typeof a.get!=='function'||typeof a.set!=='function'||!a.enumerable||!a.configurable||a.get.name!=='get '+key||a.set.name!=='set '+key||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,key))throw 'canonical meter numeric attributes';}if(x.value!==20||x.min!==10||x.max!==30||x.low!==15||x.high!==25||x.optimum!==18||x.labels[0]!==document.getElementById('label'))throw 'actual ordered gauge';"#);
}
#[test]
fn meter_numeric_actual_attribute_clamps_keep_raw_producers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('meter');x.setAttribute('min','  +4e1tail');if(x.min!==40||x.max!==40||x.value!==40||x.low!==40||x.high!==40||x.optimum!==40)throw 'minimum dominates range';x.setAttribute('max','100');x.setAttribute('low','90');x.setAttribute('high','50');x.setAttribute('optimum','200');if(x.min!==40||x.max!==100||x.value!==40||x.low!==90||x.high!==90||x.optimum!==100)throw 'ordered clamp';x.value=-3;x.max=0;if(x.getAttribute('value')!=='-3'||x.getAttribute('max')!=='0'||x.max!==40||x.value!==40)throw 'unclamped numeric setter attributes';"#);
}
#[test]
fn meter_numeric_inert_defaults_conversion_and_current_bounds(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','meter');if(x.value!==0||x.min!==0||x.max!==1||x.low!==0||x.high!==1||x.optimum!==0.5)throw 'default gauge';x.min=-10;x.max=10;x.low=-4;x.high=4;x.optimum=99;x.value=-99;if(x.value!==-10||x.optimum!==10||x.low!==-4||x.high!==4)throw 'inert numeric clamps';var calls=0;x.value={valueOf:function(){calls++;x.min=-20;return -15;}};if(calls!==1||x.min!==-20||x.value!==-15)throw 'conversion current attributes';var caught=false;try{x.high=Infinity;}catch(e){caught=e instanceof TypeError;}if(!caught||x.high!==4)throw 'finite meter doubles';"#);
}

// Meter numeric conversion and concrete metadata boundaries.
#[test]
fn meter_numeric_finite_conversion_observers_and_unclamped_negative_maximum(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('meter'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','min','max','low','high','optimum']){var old=x.getAttribute(key),a=x.getAttributeNode(key);for(var n of [NaN,Infinity,-Infinity,undefined,Symbol('n'),BigInt(1)]){var caught=false;try{x[key]=n;}catch(e){caught=e instanceof TypeError;}if(!caught||a.value!==old||watch.takeRecords().length)throw 'finite meter refusal';}x[key]=-5;var records=watch.takeRecords();if(a.value!=='-5'||records.length!==1||records[0].attributeName!==key||records[0].oldValue!==old||x.getAttributeNode(key)!==a)throw 'actual finite setter';}if(x.min!==-5||x.max!==-5||x.value!==-5||x.low!==-5||x.high!==-5||x.optimum!==-5)throw 'negative equal range';var marker={},caught;try{x.value={valueOf:function(){x.max=20;throw marker;}};}catch(e){caught=e;}var records=watch.takeRecords();if(caught!==marker||x.value!==-5||x.max!==20||records.length!==1||records[0].attributeName!=='max')throw 'author conversion effects';"#);
}
#[test]
fn meter_numeric_native_inert_raw_attributes_aliases_namespace_and_fallbacks(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','meter');"}else{"var x=document.getElementById('meter');"});
 run(&mut d,&mut f,&mut p,r#"for(var key of ['value','min','max','low','high','optimum']){x.setAttribute(key,'2');var a=x.getAttributeNode(key);a.value=' +3e1suffix';if(a.value!==' +3e1suffix')throw 'scalar Attr';a.nodeValue='4\ud800tail';if(a.value!=='4\ud800tail')throw 'raw Attr nodeValue';a.textContent='\ud8005';if(a.value!=='\ud8005')throw 'raw Attr textContent';x.setAttributeNS('urn:foreign',key,'99');x.setAttributeNS(null,key.toUpperCase(),'88');if(x.getAttributeNodeNS(null,key)!==a)throw 'namespace exact attribute';}if(x.min!==0||x.max!==1||x.value!==0||x.low!==0||x.high!==1||x.optimum!==0.5)throw 'invalid raw defaults';x.setAttribute('min','1e309');x.setAttribute('max','1e309');x.setAttribute('value','1e309');x.setAttribute('low','1e309');x.setAttribute('high','1e309');x.setAttribute('optimum','1e309');if(x.min!==0||x.max!==1||x.value!==0||x.low!==0||x.high!==1||x.optimum!==0.5)throw 'overflow defaults';x.setAttribute('min','-10');x.setAttribute('max','10');x.removeAttribute('optimum');x.setAttribute('value',' +.5e1tail');if(x.value!==5||x.optimum!==0)throw 'prefix and midpoint';"#);}
}
#[test]
fn meter_numeric_extreme_midpoint_and_ordered_ranges(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','meter');x.min=1e308;x.max=1.6e308;if(x.optimum!==1.3e308||!Number.isFinite(x.optimum))throw 'overflow safe positive midpoint';x.min=-1.6e308;x.max=-1e308;if(x.optimum!==-1.3e308)throw 'overflow safe negative midpoint';x.min=-1.6e308;x.max=1.6e308;if(x.optimum!==0)throw 'opposite extreme midpoint';x.min=10;x.max=0;x.low=100;x.high=-100;if(x.max!==10||x.value!==10||x.low!==10||x.high!==10||x.optimum!==10)throw 'inverted range collapses';x.min=-10;x.max=10;x.low=9;x.high=-9;x.optimum=-99;if(x.low!==9||x.high!==9||x.optimum!==-10)throw 'high follows low optimum independent';"#);
}
#[test]
fn meter_numeric_concrete_brands_author_overrides_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('meter'),C=HTMLMeterElement,P=C.prototype,calls=0,values=[20,10,30,15,25,18],i=0;for(var key of ['value','min','max','low','high','optimum']){var a=Object.getOwnPropertyDescriptor(P,key),expected=values[i++];for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','meter'),new Document().createElementNS('http://www.w3.org/1999/xhtml','METER'),document.createElement('progress')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'meter getter brand';caught=false;try{a.set.call(bad,{valueOf:function(){calls++;return 1;}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'meter setter brand before conversion';}Object.defineProperty(x,key,{value:'author',writable:true,configurable:true});if(x[key]!=='author'||a.get.call(x)!==expected)throw 'actual meter authority';delete x[key];if(x[key]!==expected||Object.hasOwn(x,key))throw 'restored inherited meter metadata';}delete window.HTMLMeterElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved meter interface';"#);
}
#[test]
fn meter_numeric_inert_clone_adoption_and_exact_attribute_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','m:meter');x.min=-10;x.max=30;x.value=5;x.low=0;x.high=20;x.optimum=10;var clone=x.cloneNode(false),a=clone.getAttributeNode('value'),target=new Document();target.adoptNode(x);if(x.ownerDocument!==target||x.value!==5||clone.value!==5||clone.low!==0||clone.high!==20||clone.optimum!==10||a===x.getAttributeNode('value'))throw 'actual clone/adoption';x.value=25;if(x.value!==25||clone.value!==5||a.value!=='5')throw 'independent cloned attributes';"#);
}

#[test]
fn meter_numeric_saved_child_origin_precedes_number_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('meter'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLMeterElement,a=Object.getOwnPropertyDescriptor(C.prototype,'value'),calls=0;if(C===HTMLMeterElement||a.get.call(x)!==20)throw 'captured numeric getter';");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-meter.test/",&crate::navigation::Location::home()).unwrap());for source in ["a.get.call(x);","a.set.call(x,{valueOf:function(){calls++;return 3;}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://meter-numeric.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,23);if(a.get.call(x)!==23||x.max!==30)throw 'numeric origin recovery';");}

// Use a longer replacement than the setup numeric formatter buffer so storage must grow.
#[test]
fn meter_numeric_writer_refusal_preserves_native_and_inert_records_and_recovers(){for inert in [false,true]{for(source,key)in[("x.value=123456789012345.5;","value"),("x.max=123456789012345.5;","max"),("x.min=123456789012345.5;","min"),("x.low=123456789012345.5;","low"),("x.high=123456789012345.5;","high"),("x.optimum=123456789012345.5;","optimum"),("x.setAttribute('value','123456789012345.5');","value"),("attr.value='123456789012345.5';","value"),("attr.nodeValue='123456789012345.5';","value"),("attr.textContent='123456789012345.5';","value")]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','meter');x.setAttribute('value','2');x.setAttribute('max','10');"}else{"var x=document.getElementById('meter');x.value=2;x.max=10;"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('value'),max=x.getAttributeNode('max'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("numeric writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='2'||max.value!=='10'||watch.takeRecords().length)throw 'atomic numeric writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,&format!("var records=watch.takeRecords();if(x.getAttribute('{key}')!=='123456789012345.5'||records.length!==1||records[0].attributeName!=='{key}'||x.getAttributeNode('value')!==attr||x.getAttributeNode('max')!==max)throw 'fresh numeric writer recovery';"));}}}}

#[test]
fn meter_numeric_reads_require_no_copy_string_or_new_storage_and_recover(){
 for(method,expected)in[(script_meter_numeric::VALUE_GET,20.0),(script_meter_numeric::MIN_GET,10.0),(script_meter_numeric::MAX_GET,30.0),(script_meter_numeric::LOW_GET,15.0),(script_meter_numeric::HIGH_GET,25.0),(script_meter_numeric::OPTIMUM_GET,18.0)]{
  for inert in [false,true]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,"var numeric=new Document().createElementNS('http://www.w3.org/1999/xhtml','meter');numeric.min=10;numeric.max=30;numeric.value=20;numeric.low=15;numeric.high=25;numeric.optimum=18;");let Value::Host(object)=p.runtime.execute("numeric;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert meter handle")};object}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("meter")).unwrap())};
   let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.copy_work=0;p.state.limits.host.string_bytes=0;p.state.retained_limit=p.state.retained;}}
   let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.meter_numeric_get(object,method);if mode==2{assert!(matches!(result.unwrap(),Value::Number(n)if n==expected));}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time"),"{e}");}
   assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.meter_numeric_get(object,method).is_ok());
  }}
 }
}
